// ─── File: CachePenetrationDemo.java ───
// Defends against cache penetration (requests for keys that don't exist):
// Bloom filter (no false negatives) rejects non-existent ids before any lookup,
// negative caching (sentinel + short TTL) absorbs repeated/false-positive misses.
import java.util.*;
import java.util.logging.*;

public class CachePenetrationDemo {
    private static final Logger log = Logger.getLogger("PEN");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountDatabase db = new AccountDatabase();
        BloomFilter bloom = new BloomFilter(100_000, 3);
        for (String id : db.allIds()) bloom.add(id);   // populate with all REAL ids
        Cache cache = new Cache(5);
        AccountService service = new AccountService(db, bloom, cache);

        // Benign penetration: same non-existent id requested repeatedly.
        log.info("=== Benign: repeated misses for a non-existent id ===");
        for (int i = 0; i < 5; i++) service.getBalance("SAV9999", 1_000_000L + i);
        log.info(() -> "DB hits after 5 repeated misses: " + db.hitCount()
                + " (Bloom rejected most; negative cache absorbed rest)");

        // Attack: a wide spread of distinct random non-existent ids.
        log.info("=== Attack: 10,000 distinct random non-existent ids ===");
        db.resetHits();
        for (int i = 0; i < 10_000; i++) service.getBalance("RANDOM" + i, 2_000_000L);
        log.info(() -> "DB hits during 10,000-id attack: " + db.hitCount()
                + " (Bloom rejected all non-existent → DB shielded)");

        // Legitimate existing account still works (Bloom says 'possibly', cache→DB).
        log.info("=== Legitimate existing account still served ===");
        db.resetHits();
        log.info(() -> service.getBalance("SAV2001", 3_000_000L));
        log.info(() -> service.getBalance("SAV2001", 3_000_001L) + " (2nd read = cache hit)");
    }
}

// ─── db/AccountDatabase.java (source of truth) ───
class AccountDatabase {
    private static final Logger log = Logger.getLogger("PEN");
    private final Map<String, String> rows = new HashMap<>(Map.of(
        "SAV2001","1000000", "CUR3001","250000"));
    private int hits = 0;
    String load(String id) { hits++; return rows.get(id); }  // null if not found
    Set<String> allIds() { return rows.keySet(); }
    int hitCount() { return hits; } void resetHits() { hits = 0; }
}

// ─── filter/BloomFilter.java (space-efficient, NO false negatives) ───
class BloomFilter {
    private final boolean[] bits; private final int k;  // k hash functions
    BloomFilter(int size, int hashes) { bits = new boolean[size]; k = hashes; }
    void add(String key) { for (int i = 0; i < k; i++) bits[idx(key, i)] = true; }
    // "mightContain": all bits set → possibly present; any bit unset → DEFINITELY absent.
    boolean mightContain(String key) {
        for (int i = 0; i < k; i++) if (!bits[idx(key, i)]) return false;  // no false negatives
        return true;
    }
    private int idx(String key, int i) {
        int h = (key + ":" + i).hashCode();
        return Math.floorMod(h, bits.length);
    }
}

// ─── cache/Cache.java (positive values + negative sentinel) ───
class Cache {
    static final String NOT_FOUND = "__NEG__";   // sentinel for "does not exist"
    private final Map<String, long[]> meta = new HashMap<>();   // key → [expiry]
    private final Map<String, String> value = new HashMap<>();
    private final long negTtlSec;
    Cache(long negTtlSec) { this.negTtlSec = negTtlSec; }
    String get(String key, long now) {
        long[] m = meta.get(key);
        if (m != null && now < m[0]) return value.get(key);
        return null;  // miss or expired
    }
    void putPositive(String key, String v, long now) { value.put(key, v); meta.put(key, new long[]{now + 30_000}); }
    void putNegative(String key, long now) { value.put(key, NOT_FOUND); meta.put(key, new long[]{now + negTtlSec * 1000}); }
}

// ─── service/AccountService.java (bloom → cache → DB) ───
class AccountService {
    private static final Logger log = Logger.getLogger("PEN");
    private final AccountDatabase db; private final BloomFilter bloom; private final Cache cache;
    AccountService(AccountDatabase db, BloomFilter bloom, Cache cache) { this.db = db; this.bloom = bloom; this.cache = cache; }

    String getBalance(String id, long now) {
        // 1) Bloom filter: if definitely absent, skip cache AND DB entirely.
        if (!bloom.mightContain(id)) return "NOT FOUND (bloom rejected, no DB lookup)";
        // 2) Cache: positive value or negative sentinel.
        String cached = cache.get(id, now);
        if (cached != null) {
            return cached.equals(Cache.NOT_FOUND) ? "NOT FOUND (negative cache)" : "balance=" + cached;
        }
        // 3) DB (only reached for existing ids or rare Bloom false positives).
        String v = db.load(id);
        if (v == null) { cache.putNegative(id, now); return "NOT FOUND (DB, cached negative)"; }
        cache.putPositive(id, v, now);
        return "balance=" + v;
    }
}

